(function(){"use strict";function n(){document.querySelectorAll("[data-basket-form]").forEach(function(e){e.addEventListener("submit",function(i){window.fetch&&(i.preventDefault(),fetch(e.getAttribute("action"),{method:"POST",body:new FormData(e),credentials:"same-origin",headers:{"X-Requested-With":"fetch",Accept:"application/json"}}).then(function(t){return t.json().then(function(o){if(!t.ok)throw new Error(o.message);return o})}).then(function(){window.location.reload()}).catch(function(t){window.OKV&&window.OKV.toast&&window.OKV.toast(t.message||"We could not update your basket.","error")}))})})}document.readyState==="loading"?document.addEventListener("DOMContentLoaded",n):n()})();
